const afterEach: AfterEach = async ({ reporting, canvasElement, globals }) => {
  try {
    // We only run this through ghost stories runs
    if (!globals.ghostStories) {
      return;
    }

    const emptyRender = isEmptyRender(canvasElement.firstChild ?? canvasElement);

    if (emptyRender) {
      reporting.addReport({
        type: 'render-analysis',
        version: 1,
        result: {
          emptyRender,
        },
        status: 'warning',
      });
    }
  } catch (error) {
    // Ghost Stories analysis is non-critical; log but don't throw
    logger.warn('[Ghost Stories] Error during render analysis:', error);
  }
};
